const source = $json.metadata && typeof $json.metadata === 'object' && !Array.isArray($json.metadata)
  ? $json.metadata
  : $json;

const metadata = {
  novel_uuid: String(source.novel_uuid ?? source.uuid ?? '').trim(),
  novel_slug: String(source.novel_slug ?? source.slug ?? '').trim(),
  novel_title: String(source.novel_title ?? source.title ?? '').trim(),
  novel_genre: String(source.novel_genre ?? source.genre ?? '').trim(),
  created_by: String(source.created_by ?? $json.created_by ?? 'Novel Studio').trim(),
};

const missing = Object.entries(metadata)
  .filter(([, value]) => !value)
  .map(([field]) => field);

if (missing.length > 0) {
  throw new Error(`Missing required novel metadata: ${missing.join(', ')}`);
}

return [{ json: { metadata } }];

function createUuid() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (character) => {
    const randomValue = Math.floor(Math.random() * 16);
    const value = character === 'x' ? randomValue : (randomValue & 0x3) | 0x8;
    return value.toString(16);
  });
}

const { metadata, folder_manifest, file_manifest } = $json;
const workspaceName = `${metadata.novel_title} Workspace`;

return [{
  json: {
    workspace: {
      workspace_uuid: createUuid(),
      workspace_name: workspaceName,
      novel_uuid: metadata.novel_uuid,
      novel_slug: metadata.novel_slug,
      novel_title: metadata.novel_title,
      novel_genre: metadata.novel_genre,
      root_folder_name: metadata.novel_slug,
      folder_manifest,
      file_manifest,
      workspace_version: '1.0',
      created_at: new Date().toISOString(),
      created_by: metadata.created_by,
    },
  },
}];

return [{
  json: {
    route: 'workspace.created',
    status: 'ready',
    workspace: $json.workspace,
    next_workflow: 'WF-003-P02',
  },
}];
